#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, maximum = 0;
    cin >> n;
    vector<long long> frequency(100001);
    for (int i = 0; i < n; ++i) {
        int value;
        cin >> value;
        ++frequency[value];
        maximum = max(maximum, value);
    }
    long long twoBack = 0, oneBack = 0;
    for (int value = 1; value <= maximum; ++value) {
        long long current = max(oneBack, twoBack + value * frequency[value]);
        twoBack = oneBack;
        oneBack = current;
    }
    cout << oneBack << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    array<int, 3> cuts;
    cin >> n >> cuts[0] >> cuts[1] >> cuts[2];
    vector<int> pieces(n + 1, -1);
    pieces[0] = 0;
    for (int length = 1; length <= n; ++length) {
        for (int cut : cuts) {
            if (length >= cut && pieces[length - cut] != -1) {
                pieces[length] = max(pieces[length], pieces[length - cut] + 1);
            }
        }
    }
    cout << pieces[n] << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> reversalCost(n);
    for (long long &value : reversalCost) cin >> value;
    vector<array<string, 2>> oriented(n);
    for (auto &versions : oriented) {
        cin >> versions[0];
        versions[1] = versions[0];
        reverse(versions[1].begin(), versions[1].end());
    }
    const long long infinity = 4000000000000000000LL;
    array<long long, 2> cost{0, reversalCost[0]};
    for (int i = 1; i < n; ++i) {
        array<long long, 2> next{infinity, infinity};
        for (int previous = 0; previous < 2; ++previous) {
            if (cost[previous] == infinity) continue;
            for (int current = 0; current < 2; ++current) {
                if (oriented[i - 1][previous] <= oriented[i][current]) {
                    next[current] = min(next[current], cost[previous] + current * reversalCost[i]);
                }
            }
        }
        cost = next;
    }
    long long answer = min(cost[0], cost[1]);
    cout << (answer == infinity ? -1 : answer) << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, maximumWeight, threshold;
    cin >> n >> maximumWeight >> threshold;
    const long long mod = 1000000007;
    vector<array<long long, 2>> ways(n + 1);
    ways[0][0] = 1;
    for (int sum = 0; sum < n; ++sum) {
        for (int seen = 0; seen < 2; ++seen) {
            for (int weight = 1; weight <= maximumWeight && sum + weight <= n; ++weight) {
                int nextSeen = seen || weight >= threshold;
                long long &target = ways[sum + weight][nextSeen];
                target = (target + ways[sum][seen]) % mod;
            }
        }
    }
    cout << ways[n][1] << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    const int infinity = 1000000;
    array<int, 3> cost{0, infinity, infinity};
    for (int day = 0; day < n; ++day) {
        int mask;
        cin >> mask;
        array<int, 3> next{1 + min({cost[0], cost[1], cost[2]}), infinity, infinity};
        if (mask & 1) next[1] = min(cost[0], cost[2]);
        if (mask & 2) next[2] = min(cost[0], cost[1]);
        cost = next;
    }
    cout << min({cost[0], cost[1], cost[2]}) << '\n';
}
